BEGIN TRANSACTION;
CREATE TABLE "action_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action" varchar(200) NOT NULL, "object_repr" varchar(200) NOT NULL, "ip_address" char(39) NULL, "created_at" datetime NOT NULL, "user_id" bigint NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "alumni_profiles" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "last_name" varchar(100) NOT NULL, "first_name" varchar(100) NOT NULL, "middle_name" varchar(100) NOT NULL, "grad_year" smallint unsigned NOT NULL CHECK ("grad_year" >= 0), "workplace" varchar(255) NOT NULL, "position" varchar(150) NOT NULL, "photo" varchar(100) NOT NULL, "is_mentor" bool NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED, "program_id" bigint NULL REFERENCES "programs" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "club_documents" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "description" varchar(300) NOT NULL, "file" varchar(100) NOT NULL, "uploaded_at" datetime NOT NULL, "uploaded_by_id" bigint NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "event_registrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "registered_at" datetime NOT NULL, "attended" bool NOT NULL, "event_id" bigint NOT NULL REFERENCES "events" ("id") DEFERRABLE INITIALLY DEFERRED, "profile_id" bigint NOT NULL REFERENCES "alumni_profiles" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_event_profile" UNIQUE ("event_id", "profile_id"));
CREATE TABLE "event_statuses" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(20) NOT NULL UNIQUE, "name" varchar(50) NOT NULL);
CREATE TABLE "events" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "description" text NOT NULL, "start_at" datetime NOT NULL, "place" varchar(255) NOT NULL, "capacity" integer unsigned NOT NULL CHECK ("capacity" >= 0), "created_by_id" bigint NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED, "status_id" bigint NOT NULL REFERENCES "event_statuses" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "faculties" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "feedback" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "email" varchar(254) NOT NULL, "topic" varchar(200) NOT NULL, "message" text NOT NULL, "consent" bool NOT NULL, "created_at" datetime NOT NULL, "is_processed" bool NOT NULL, "answer" text NOT NULL, "processed_by_id" bigint NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "feedback_consent_true" CHECK ("consent"));
CREATE TABLE "gallery_photos" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "image" varchar(100) NOT NULL, "taken_at" date NULL, "uploaded_at" datetime NOT NULL, "uploaded_by_id" bigint NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "graduate_records" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "last_name" varchar(100) NOT NULL, "first_name" varchar(100) NOT NULL, "middle_name" varchar(100) NOT NULL, "grad_year" smallint unsigned NOT NULL CHECK ("grad_year" >= 0), "imported_at" datetime NOT NULL, "program_id" bigint NOT NULL REFERENCES "programs" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_graduate_record" UNIQUE ("last_name", "first_name", "middle_name", "program_id", "grad_year"));
CREATE TABLE "membership_requests" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "last_name" varchar(100) NOT NULL, "first_name" varchar(100) NOT NULL, "middle_name" varchar(100) NOT NULL, "email" varchar(254) NOT NULL, "grad_year" smallint unsigned NOT NULL CHECK ("grad_year" >= 0), "consent_version" varchar(20) NOT NULL, "submitted_at" datetime NOT NULL, "reviewed_at" datetime NULL, "comment" varchar(255) NOT NULL, "reviewed_by_id" bigint NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED, "program_id" bigint NOT NULL REFERENCES "programs" ("id") DEFERRABLE INITIALLY DEFERRED, "status_id" bigint NOT NULL REFERENCES "request_statuses" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "news" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "summary" varchar(300) NOT NULL, "body" text NOT NULL, "image" varchar(100) NOT NULL, "published_at" datetime NULL, "author_id" bigint NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED, "category_id" bigint NOT NULL REFERENCES "news_categories" ("id") DEFERRABLE INITIALLY DEFERRED);

