CREATE TABLE "news_categories" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(20) NOT NULL UNIQUE, "name" varchar(50) NOT NULL);
CREATE TABLE "notifications" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "text" varchar(300) NOT NULL, "url" varchar(200) NOT NULL, "is_read" bool NOT NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "partners" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL UNIQUE, "description" text NOT NULL, "site" varchar(200) NOT NULL, "logo" varchar(100) NOT NULL);
CREATE TABLE "pd_consents" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "version" varchar(20) NOT NULL, "given_at" datetime NOT NULL, "revoked_at" datetime NULL, "user_id" bigint NOT NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "programs" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(10) NOT NULL, "name" varchar(150) NOT NULL, "faculty_id" bigint NOT NULL REFERENCES "faculties" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_program_code_name" UNIQUE ("code", "name"));
CREATE TABLE "request_statuses" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(20) NOT NULL UNIQUE, "name" varchar(50) NOT NULL);
CREATE TABLE "roles" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(20) NOT NULL UNIQUE, "name" varchar(50) NOT NULL);
CREATE TABLE "users" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "email" varchar(254) NOT NULL UNIQUE, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "role_id" bigint NOT NULL REFERENCES "roles" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "vacancies" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "description" text NOT NULL, "salary" varchar(100) NOT NULL, "is_internship" bool NOT NULL, "closes_at" date NULL, "created_at" datetime NOT NULL, "partner_id" bigint NOT NULL REFERENCES "partners" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "vacancy_responses" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "resume_file" varchar(100) NOT NULL, "cover_letter" text NOT NULL, "created_at" datetime NOT NULL, "profile_id" bigint NOT NULL REFERENCES "alumni_profiles" ("id") DEFERRABLE INITIALLY DEFERRED, "vacancy_id" bigint NOT NULL REFERENCES "vacancies" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_vacancy_profile" UNIQUE ("vacancy_id", "profile_id"));
