INSERT INTO "events" VALUES(4,'Экскурсия в офис компании-партнёра','Экскурсия в офис компании-партнёра. Участие бесплатное, необходима регистрация на портале. Программа мероприятия будет направлена участникам заранее.','2026-11-26 15:00:00','Сбор у главного корпуса',15,2,2);
INSERT INTO "events" VALUES(5,'Круглый стол «Наставничество для студентов»','Круглый стол «Наставничество для студентов». Участие бесплатное, необходима регистрация на портале. Программа мероприятия будет направлена участникам заранее.','2026-12-05 15:00:00','Главный корпус, ауд. 210',25,2,2);
